"""Trusted OpenKapsel Podman container names (never accept arbitrary CLI targets)."""
from __future__ import annotations

import re

# Names are generated by PodmanBackend / Mapping Client shell task code.
SERVER_CONTAINER_RE = re.compile(r"openkapsel-[0-9a-f]{8}-[0-9a-f]{12}\Z")
CLIENT_CONTAINER_RE = re.compile(
    r"openkapsel-client-(?:[A-Za-z0-9_-]{24}-)?[A-Za-z0-9]{4}\Z"
)


def is_server_container(name: object) -> bool:
    return type(name) is str and SERVER_CONTAINER_RE.fullmatch(name) is not None


def is_client_container(name: object) -> bool:
    return type(name) is str and CLIENT_CONTAINER_RE.fullmatch(name) is not None


def is_mapping_job_container(name: object, mapping_id: str, task_id: str) -> bool:
    return (is_client_container(name)
            and type(mapping_id) is str
            and type(task_id) is str
            and name == f"openkapsel-client-{mapping_id}-{task_id[1:-1]}")
